for (const t of tipos) {
  const a = ampliacionesHerramienta[t.slug];
  t.chips = ['Selección por maniobra', 'Inspección física', 'Resguardo seguro'];
  t.normas = [{ norma: `Herramientas manuales: ${t.nombre}`, alcance: `No se publica una norma específica para ${t.nombre.toLowerCase()}; confirma las especificaciones del fabricante en la cotización.` }];
  t.bloques.push(...a.bloques);
  t.errores = a.errores;
  t.faq = a.faq;
}

const cierreTecnico: Record<string, Tipo['bloques'][number]> = {
  'hacha-de-bombero': { h2: 'Asignación por unidad y relevo', parrafos: ['Una unidad que lleva hachas debe identificar cuál corresponde a cada soporte y revisar que la funda no se haya perdido durante el relevo. El control no se limita al inventario: confirma que el filo queda apartado de la mano al liberar el seguro y que el mango no queda atrapado por otra herramienta.', 'Cuando se piden varias hachas, la orden debe separar las de intervención de las de reserva. Esa distinción facilita revisar cantidades, fundas y mangos compatibles, y evita que una pieza de porte se entregue por error donde se había previsto una de mango largo.'] },
  'barra-halligan': { h2: 'Compatibilidad del soporte con la barra', parrafos: ['El soporte debe abrazar el cuerpo de la barra sin forzar horquilla, cuña, pala o pico. Antes de comprar varios, presenta la longitud declarada contra el compartimiento y verifica que la liberación no obligue a sujetar un extremo de trabajo. Una retención que vibra desgasta el acabado y puede deformar sus partes más expuestas.', 'En una recepción institucional, asigna ubicación e identificación individual. Así es posible detectar una Halligan faltante, intercambiada por otra longitud o devuelta con una punta dañada. La revisión visual debe hacerse antes de cerrar el compartimiento, no hasta que la barra se requiera en una emergencia.'] },
  'gancho-bichero': { h2: 'Montaje y almacenamiento del bichero', parrafos: ['El soporte del bichero debe sujetar el asta en más de un punto cuando su longitud lo requiera; una sola abrazadera permite vibración y golpea la cabeza contra el compartimiento. Verifica que la funda cubra la punta aun cuando el personal retire el gancho con guantes y que el gancho no roce puertas, mangueras o ERA.', 'Para dotaciones con varias longitudes, etiqueta el soporte y la herramienta con la medida autorizada. Mezclar astas parecidas hace difícil detectar una sustitución y cambia el alcance previsto. La recepción debe probar extracción, reingreso y cierre del gabinete con cada medida solicitada.'] },
  pulaski: { h2: 'Distribución de Pulaskis en la cuadrilla', parrafos: ['Una Pulaski se asigna donde el plan prevé alternar corte de vegetación y remoción de suelo. Antes de solicitar cantidades, cuenta las tareas de línea y evita equipar a toda la cuadrilla con la misma cabeza combinada si también se requieren dientes para combustible fino o hojas anchas para raspar.', 'Identifica cada herramienta con su protector y posición de transporte, sin cubrir la zona de unión entre cabeza y mango. Esa disciplina permite ver una cuña salida o corrosión inicial al abrir el compartimiento. Un mango de reemplazo debe conservar el largo y diseño compatibles con la cabeza publicada.'] },
  mcleod: { h2: 'Cantidad y función en una línea forestal', parrafos: ['El número de McLeod se calcula por las posiciones que requieren raspar y ordenar combustible fino, no por una cantidad uniforme de herramientas. En la requisición distingue McLeod, Pulaski y rastrillo; las tres piezas pueden viajar juntas, pero su cabeza responde a una tarea distinta y requiere un lugar propio.', 'Durante el inventario, deja visible la cara de dientes y la hoja para detectar deformación. No apiles la cabeza bajo objetos pesados ni cuelgues la herramienta por un solo diente. La manera de guardar un McLeod protege tanto la geometría de trabajo como la seguridad de quien abre el compartimiento.'] },
  'rastrillo-forestal': { h2: 'Reparto por combustible y vehículo', parrafos: ['El rastrillo se entrega a posiciones donde se necesita reunir material ligero; su cantidad depende de la anchura de trabajo y de la carga vegetal esperada. Documenta cuántos van en cada vehículo y reserva fundas o espacios donde los dientes no queden enfrentados a bolsas, chaquetones o líneas.', 'Para conservar consistencia, compra cabezas con la misma configuración cuando la cuadrilla necesita barrer un mismo tipo de combustible. Si se aceptan variaciones, anótalas por separado. De ese modo, el responsable puede prever qué pieza lleva dientes más cerrados y no descubre la diferencia hasta la salida al terreno.'] },
  batefuego: { h2: 'Preparación antes de distribuir batefuegos', parrafos: ['Antes de asignar batefuegos, extiende cada pala sobre una superficie plana y confirma que recupera su forma sin rajaduras. Esta revisión es distinta de la de un rastrillo: aquí importa que la lámina flexible conserve la superficie que hace contacto con llama baja y combustible vegetal.', 'Incluye en el control de vehículo la ubicación donde la pala queda libre de dobleces. Si se transportan varios, intercala sus láminas con separación que no comprima los bordes. La orden debe indicar qué unidades recibirán la herramienta para evitar concentrar todas las piezas en una sola brigada.'] },
  'bomba-de-mochila-forestal': { h2: 'Control de agua y refacciones', parrafos: ['La planeación de una bomba de mochila incluye dónde se llenará y quién revisará sellos, tapa y boquilla antes de salida. La capacidad declarada ayuda a dimensionar el traslado de agua, pero no expresa por sí sola la disponibilidad: una manguera incompatible o un arnés roto inmovilizan el conjunto completo.', 'Registra la ubicación de cada mochila, el juego de repuestos compatible y la fecha de su última prueba de estanqueidad. Al recibir varias unidades, comprueba que una tapa, sello o boquilla de reemplazo corresponda al modelo adquirido; mezclar conexiones por apariencia puede producir fugas o impedir la descarga.'] }
};

for (const t of tipos) t.bloques.push(cierreTecnico[t.slug]);

seccion.intro.push('Una partida bien definida incluye más que la herramienta. Asigna responsables, ubicación dentro de cada vehículo, protectores de punta o filo y una forma de registrar daño. Al recibir, compara material, configuración y accesorios contra la orden; el control inicial evita integrar piezas que no corresponden a la maniobra prevista.', 'Para sostener la disponibilidad, separa la inspección de la improvisación. Limpieza, secado y resguardo permiten observar la condición; no justifican enderezar, soldar o encintar una pieza comprometida. El reemplazo se decide por el estado físico, las instrucciones del fabricante y el criterio técnico establecido por la corporación.');
seccion.intro.push('La distribución por unidad debe reflejar los escenarios de respuesta y no una lista uniforme para todos los vehículos. Identifica qué herramientas viajan en acceso, cuáles se destinan a línea forestal y cuáles requieren fundas o compartimientos separados. Esta planeación permite realizar inventarios de inicio y cierre de turno sin confundir funciones ni dejar equipo expuesto.');
seccion.faq.push({ q: '¿Qué se registra en la recepción?', a: 'Modelo, cantidad, ubicación, estado físico, accesorios y responsable de la inspección inicial.' }, { q: '¿Por qué incluir soporte en la compra?', a: 'Porque una herramienta sin sujeción puede dañarse, dañar otros equipos o ser inaccesible en traslado.' });

